scripts.script:
while task.wait(0.1) do
for _,v in workspace:GetChildren() do
    if v:FindFirstChild("Humanoid") and v.Name ~= game.Players.LocalPlayer.Character.Name then
local args = {
    game:GetService("Players").LocalPlayer.Character:FindFirstChildOfClass("Tool"),
    v,
    {
        ClientMaxHits = 1,
        ClientHitboxData = {
            Offset = vector.create(0, 0, -3),
            HitboxAmount = 6,
            Size = vector.create(3, 5, 5),
            Duration = 0.1,
            DelayBetweenHitboxes = 0.05,
            SpawnDelay = 0.7
        },
        ClientSoundData = {
            OnSwing = "Swing",
            OnHit = "Hit"
        }
    }
}
game:GetService("ReplicatedStorage"):WaitForChild("Resources"):WaitForChild("Remotes"):WaitForChild("HitboxHit"):FireServer(unpack(args))
end
end
end
